import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadNamdaphaData(){const e=readFileSync(resolve(__dirname,"../../frontend/namdapha-national-park-explorer/namdapha-data.js"),"utf-8");return new Function(e+"\nreturn { NAMDAPHA_INFO, ALTITUDE_ZONES, FOUR_BIG_CATS, RARE_MAMMALS, BIRDLIFE, TREKKING_ROUTES, HISTORY_TIMELINE, MAP_HOTSPOTS, GALLERY_IMAGES };")()}function loadNationalParksData(){const e=readFileSync(resolve(__dirname,"../../frontend/national-parks-explorer/data.js"),"utf-8");return new Function(e+"\nreturn { NATIONAL_PARKS };")()}function loadSearchIndex(){const e=readFileSync(resolve(__dirname,"../../search-index.js"),"utf-8");return new Function("window",e+"\nreturn window.indiaSearchIndex;")({})}describe("Namdapha National Park Explorer — Data & Integration Tests",()=>{let e;beforeAll(()=>{e=loadNamdaphaData()}),describe("NAMDAPHA_INFO metadata",()=>{it("contains correct park metadata for Namdapha",()=>{expect(e.NAMDAPHA_INFO.id).toBe("namdapha"),expect(e.NAMDAPHA_INFO.name).toBe("Namdapha National Park"),expect(e.NAMDAPHA_INFO.state).toBe("Arunachal Pradesh"),expect(e.NAMDAPHA_INFO.establishedYear).toBe(1983),expect(e.NAMDAPHA_INFO.coordinates.lat).toBeCloseTo(27.4917,2),expect(e.NAMDAPHA_INFO.coordinates.lng).toBeCloseTo(96.3833,2)}),it("has quickStats array with 6 entries",()=>{expect(Array.isArray(e.NAMDAPHA_INFO.quickStats)).toBe(!0),expect(e.NAMDAPHA_INFO.quickStats.length).toBe(6)})}),describe("ALTITUDE_ZONES & FOUR_BIG_CATS",()=>{it("contains 4 altitude zones from 200m to 4,571m",()=>{expect(Array.isArray(e.ALTITUDE_ZONES)).toBe(!0),expect(e.ALTITUDE_ZONES.length).toBe(4);const t=e.ALTITUDE_ZONES.find(e=>"zone-alpine"===e.id);expect(t).toBeDefined(),expect(t.range).toContain("4,571 m")}),it("contains all 4 feline big cat species",()=>{expect(Array.isArray(e.FOUR_BIG_CATS)).toBe(!0),expect(e.FOUR_BIG_CATS.length).toBe(4);const t=e.FOUR_BIG_CATS.map(e=>e.id);expect(t).toContain("snow-leopard"),expect(t).toContain("clouded-leopard"),expect(t).toContain("common-leopard"),expect(t).toContain("bengal-tiger")})}),describe("RARE_MAMMALS & BIRDLIFE",()=>{it("contains Red Panda and Hoolock Gibbon in RARE_MAMMALS",()=>{expect(Array.isArray(e.RARE_MAMMALS)).toBe(!0),expect(e.RARE_MAMMALS.length).toBeGreaterThanOrEqual(4);const t=e.RARE_MAMMALS.find(e=>"red-panda"===e.id),a=e.RARE_MAMMALS.find(e=>"hoolock-gibbon"===e.id);expect(t).toBeDefined(),expect(a).toBeDefined()}),it("every bird species has required properties",()=>{expect(Array.isArray(e.BIRDLIFE)).toBe(!0),expect(e.BIRDLIFE.length).toBeGreaterThanOrEqual(5),e.BIRDLIFE.forEach(e=>{expect(e).toHaveProperty("id"),expect(e).toHaveProperty("name"),expect(e).toHaveProperty("scientificName"),expect(e).toHaveProperty("category"),expect(e).toHaveProperty("status"),expect(e).toHaveProperty("image"),expect(e).toHaveProperty("description")})})}),describe("TREKKING_ROUTES & MAP_HOTSPOTS",()=>{it("contains 4 wilderness trekking routes",()=>{expect(Array.isArray(e.TREKKING_ROUTES)).toBe(!0),expect(e.TREKKING_ROUTES.length).toBe(4),e.TREKKING_ROUTES.forEach(e=>{expect(e).toHaveProperty("id"),expect(e).toHaveProperty("title"),expect(e).toHaveProperty("distance"),expect(e).toHaveProperty("terrain"),expect(Array.isArray(e.camps)).toBe(!0)})}),it("MAP_HOTSPOTS has valid percentage coordinates (0-100)",()=>{expect(Array.isArray(e.MAP_HOTSPOTS)).toBe(!0),expect(e.MAP_HOTSPOTS.length).toBeGreaterThanOrEqual(5),e.MAP_HOTSPOTS.forEach(e=>{expect(e.x).toBeGreaterThanOrEqual(0),expect(e.x).toBeLessThanOrEqual(100),expect(e.y).toBeGreaterThanOrEqual(0),expect(e.y).toBeLessThanOrEqual(100)})})}),describe("Landing Page & Search Index Integration",()=>{it("Namdapha entry in NATIONAL_PARKS has explorerUrl",()=>{const e=loadNationalParksData().NATIONAL_PARKS.find(e=>"namdapha"===e.id);expect(e).toBeDefined(),expect(e.explorerUrl).toBe("../namdapha-national-park-explorer/index.html"),expect(e.state).toBe("Arunachal Pradesh")}),it("Search Index registers Namdapha National Park Explorer",()=>{const e=loadSearchIndex().find(e=>"Namdapha National Park Explorer"===e.title);expect(e).toBeDefined(),expect(e.url).toBe("frontend/namdapha-national-park-explorer/index.html")})})});